func TestClient_Interactions(t *testing.T) {
	ctx := t.Context()

	last := &apitest.LastBody{Next: apitest.Replay(t, "../../api/interactions.json")}

	c, err := NewClient(WithHTTPClient(&http.Client{Transport: last}))
	if err != nil {
		t.Fatal(err)
	}

	if out, err := c.GetPackage(ctx, "golang.org/x/time/rate", &GetPackageParams{}); err != nil {
		t.Fatalf("GetPackage: %v", err)
	} else {
		apitest.DecodedAsSent(t, "GetPackage", out, last.Body, jsonOpts)
	}

	if out, err := c.GetModule(ctx, "golang.org/x/time", &GetModuleParams{}); err != nil {
		t.Fatalf("GetModule: %v", err)
	} else {
		apitest.DecodedAsSent(t, "GetModule", out, last.Body, jsonOpts)
	}

	if out, err := c.GetVersions(ctx, "golang.org/x/time", &GetVersionsParams{
		Limit: 3,
	}); err != nil {
		t.Fatalf("GetVersions: %v", err)
	} else {
		apitest.DecodedAsSent(t, "GetVersions", out, last.Body, jsonOpts)
	}

	if out, err := c.GetPackages(ctx, "golang.org/x/time", &GetPackagesParams{}); err != nil {
		t.Fatalf("GetPackages: %v", err)
	} else {
		apitest.DecodedAsSent(t, "GetPackages", out, last.Body, jsonOpts)
	}

	if out, err := c.GetSearch(ctx, &GetSearchParams{
		Q: "xyzzy",
	}); err != nil {
		t.Fatalf("GetSearch: %v", err)
	} else {
		apitest.DecodedAsSent(t, "GetSearch", out, last.Body, jsonOpts)
	}

	if out, err := c.GetSymbols(ctx, "golang.org/x/time/rate", &GetSymbolsParams{}); err != nil {
		t.Fatalf("GetSymbols: %v", err)
	} else {
		apitest.DecodedAsSent(t, "GetSymbols", out, last.Body, jsonOpts)
	}

	if out, err := c.GetImportedBy(ctx, "golang.org/x/time/rate", &GetImportedByParams{
		Limit: 10,
	}); err != nil {
		t.Fatalf("GetImportedBy: %v", err)
	} else {
		apitest.DecodedAsSent(t, "GetImportedBy", out, last.Body, jsonOpts)
	}

	if out, err := c.GetVulns(ctx, "golang.org/x/image", &GetVulnsParams{}); err != nil {
		t.Fatalf("GetVulns: %v", err)
	} else {
		apitest.DecodedAsSent(t, "GetVulns", out, last.Body, jsonOpts)
	}
}
